"""Internal helper functions module."""
from collections.abc import Callable, Mapping
from contextlib import suppress
from functools import partial
from itertools import chain, groupby
from operator import itemgetter
from typing import TYPE_CHECKING, Literal

from pytest_durations.types import GroupBy

if TYPE_CHECKING:
    from _pytest.fixtures import FixtureDef
    from _pytest.nodes import Item

    from pytest_durations.typing import DurationListT, FunctionKeyT, FunctionMeasurementsT

    MeasurementItemT = tuple[FunctionKeyT, DurationListT]
    GroupingCbT = Callable[[MeasurementItemT], FunctionKeyT]
    GroupingKindT = Literal["test", "fixture"]


def is_shared_fixture(fixturedef: "FixtureDef") -> bool:
    """Return true if a fixture is shared."""
    return fixturedef.scope != "function"


def get_fixture_key(fixturedef: "FixtureDef", item: "Item") -> "FunctionKeyT":
    """Return fixture measurements dict key."""
    has_location = not fixturedef.baseid and fixturedef.scope == "function"
    baseid = get_test_key(item=item) if has_location else fixturedef.baseid
    return "::".join(filter(None, (baseid, fixturedef.argname)))


def get_test_key(item: "Item") -> "FunctionKeyT":
    """Return test item measurements dict key."""
    return item.nodeid


def _get_grouping_func(kind: "GroupingKindT", group_by: "GroupBy") -> "GroupingCbT":
    """Get fixture key grouping function based on a GroupBy enumeration value."""
    with suppress(KeyError):
        return _GROUPING_FUNC_MAP[kind][group_by]
    msg = f'{kind.capitalize()} grouping function for "{group_by}" not implemented'
    raise NotImplementedError(msg)


get_test_grouping_func = partial(_get_grouping_func, kind="test")
get_fixture_grouping_func = partial(_get_grouping_func, kind="fixture")


def get_grouped_measurements(
    measurements: "FunctionMeasurementsT",
    grouping_func: "GroupingCbT",
) -> "FunctionMeasurementsT":
    """Group test measurements using a provided function to get grouping keys."""
    return {
        k: list(chain(*map(itemgetter(1), v)))
        for k, v in groupby(sorted(measurements.items(), key=grouping_func), key=grouping_func)
    }


def _test_group_by_legacy(item: "MeasurementItemT") -> "FunctionKeyT":
    # keep class and test name only (old behaviour before grouping)
    return _remove_params_from_key(item[0].split("::", 1)[-1])


def _fixture_group_by_legacy(item: "MeasurementItemT") -> "FunctionKeyT":
    # keep fixture name only (old behaviour before grouping)
    return _remove_params_from_key(item[0].rsplit("::", 1)[-1])


def _group_by_module(item: "MeasurementItemT") -> "FunctionKeyT":
    # remove class and test name (keep file name)
    with suppress(IndexError):
        return item[0].split("::", 1)[-2]
    return "uncertain"


def _group_by_class(item: "MeasurementItemT") -> "FunctionKeyT":
    # remove test name (keep file and class name)
    with suppress(IndexError):
        mod = item[0].split("::", 1)[-2]
        cls = item[0].rsplit("::", 1)[-2]
        return cls if cls != mod else f"{mod}::"
    return f"uncertain::{item[0]}"


def _group_by_function(item: "MeasurementItemT") -> "FunctionKeyT":
    # remove parameters mark
    return _remove_params_from_key(item[0])


def _group_by_none(item: "MeasurementItemT") -> "FunctionKeyT":
    # keep name as is
    return item[0]


_GROUPING_FUNC_MAP: Mapping["GroupingKindT", Mapping["GroupBy", "GroupingCbT"]] = {
    "test": {
        GroupBy.LEGACY: _test_group_by_legacy,
        GroupBy.MODULE: _group_by_module,
        GroupBy.CLASS: _group_by_class,
        GroupBy.FUNCTION: _group_by_function,
        GroupBy.NONE: _group_by_none,
    },
    "fixture": {
        GroupBy.LEGACY: _fixture_group_by_legacy,
        GroupBy.MODULE: _group_by_module,
        GroupBy.CLASS: _group_by_class,
        GroupBy.FUNCTION: _group_by_function,
        GroupBy.NONE: _group_by_none,
    },
}


def _remove_params_from_key(key: str) -> str:
    return key.rsplit("[", 1)[0]

"""Helper module to get original time module functions when a time travelling package is used."""
from time import time

monotonic_impl = time

try:
    # if freezegun is installed, use its stored real function
    import freezegun
except ImportError:
    pass
else:
    freezegun.configure(extend_ignore_list=[__name__])

try:
    # if time_machine is installed, use its stored real function
    from time_machine import escape_hatch
except ImportError:
    pass
else:

    def monotonic_impl() -> float:
        """Use escape_hatch if time_machine is currently travelling, original time module otherwise."""
        return escape_hatch.time.time() if escape_hatch.is_travelling() else time()


def get_current_ticks() -> float:
    """Return uniformly increasing value in seconds."""
    return monotonic_impl()

"""Pytest plugin mixin to be used when xdist package is used."""
from typing import TYPE_CHECKING, Any, Union

import pytest

if TYPE_CHECKING:
    from _pytest.config import ExitCode
    from _pytest.main import Session
    from xdist.workermanage import WorkerController

    from pytest_durations.typing import CategoryMeasurementsT, FunctionMeasurementsT


_WORKEROUTPUT_ATTR = "workeroutput"
_PLUGIN_KEY = "pytest_durations"


class PytestDurationXdistMixin:
    """Mixin to combine measurements from xdist workers."""

    measurements: "CategoryMeasurementsT"

    @pytest.hookimpl(tryfirst=True)
    def pytest_sessionfinish(self, session: "Session", exitstatus: Union[int, "ExitCode"]) -> None:
        """Send measurements to the master process if the current session runs under pytest-xdist."""
        # for xdist, results should be added to worker output
        workeroutput: dict[str, Any] | None = getattr(session.config, _WORKEROUTPUT_ATTR, None)
        if workeroutput is not None:
            workeroutput[_PLUGIN_KEY] = dump_measurements(self.measurements)

    def pytest_testnodedown(self, node: "WorkerController", error: Any | None) -> None:
        """Merge measurements from slave processes if the current sessions runs under pytest-xdist."""
        # for xdist, results should be accumulated from workers
        workeroutput: dict[str, Any] | None = getattr(node, _WORKEROUTPUT_ATTR, None)
        if workeroutput is not None:
            node_measurements = node.workeroutput[_PLUGIN_KEY]
            load_measurements(node_measurements, self.measurements)


def dump_measurements(measurements: "CategoryMeasurementsT") -> dict[str, "FunctionMeasurementsT"]:
    """Serialize category measurement mapping with simple types only."""
    return measurements


def load_measurements(measurements: dict[str, "FunctionMeasurementsT"], destination: "CategoryMeasurementsT") -> None:
    """Deserialize category measurement mapping into an existing object."""
    for category, src_series in measurements.items():
        dst_series = destination[category]
        for key, values in src_series.items():
            dst_series.setdefault(key, []).extend(values)

